import{_ as a}from"./chunks/tcp-handshake.sZw1HXt9.js";import{_ as o,o as r,c as e,a2 as n}from"./chunks/framework.BXzK3EA4.js";const s="/img/%E7%BD%91%E7%BB%9C/osi-tcpip/tcp-teardown.svg",T=JSON.parse('{"title":"TCP 三次握手与四次挥手","description":"为什么是 3 次：确保双方都能收发。","frontmatter":{},"headers":[],"relativePath":"网络/15-tcp-handshake.md","filePath":"网络/15-tcp-handshake.md","lastUpdated":1793930980000}'),i={name:"网络/15-tcp-handshake.md"};function l(p,t,c,h,d,_){return r(),e("div",null,[...t[0]||(t[0]=[n('<h1 id="tcp-三次握手与四次挥手" tabindex="-1">TCP 三次握手与四次挥手 <a class="header-anchor" href="#tcp-三次握手与四次挥手" aria-label="Permalink to &quot;TCP 三次握手与四次挥手&quot;">​</a></h1><h3 id="_15-1-三次握手-建立连接" tabindex="-1">15.1 三次握手（建立连接） <a class="header-anchor" href="#_15-1-三次握手-建立连接" aria-label="Permalink to &quot;15.1 三次握手（建立连接）&quot;">​</a></h3><p><img src="'+a+'" alt="TCP 三次握手:客户端与服务端各确认一次收发能力,连接建立"></p><p><strong>为什么是 3 次</strong>：确保双方都能收发。</p><h3 id="_15-2-四次挥手-关闭连接" tabindex="-1">15.2 四次挥手（关闭连接） <a class="header-anchor" href="#_15-2-四次挥手-关闭连接" aria-label="Permalink to &quot;15.2 四次挥手（关闭连接）&quot;">​</a></h3><p><img src="'+s+'" alt="TCP 四次挥手:两次 FIN 加两次 ACK,客户端最后进入 TIME_WAIT 状态"></p><p><strong>为什么是 4 次</strong>：服务器可能还有数据要发，FIN 和 ACK 分开发。</p><h2 id="🎯-面试常考" tabindex="-1">🎯 面试常考 <a class="header-anchor" href="#🎯-面试常考" aria-label="Permalink to &quot;🎯 面试常考&quot;">​</a></h2><h3 id="q1-为什么是三次握手-两次不行吗" tabindex="-1">Q1：为什么是三次握手?两次不行吗? <a class="header-anchor" href="#q1-为什么是三次握手-两次不行吗" aria-label="Permalink to &quot;Q1：为什么是三次握手?两次不行吗?&quot;">​</a></h3><p>核心是<strong>让双方都确认「自己发的和对方发的都能到达」</strong>。</p><p>两次握手的问题:客户端发 SYN、服务端回 SYN+ACK 后,<strong>服务端无法确认客户端收到了自己的 ACK</strong>。 历史上有「延迟的 SYN-ACK」攻击:攻击者截获第一次 SYN 并延迟发送自己的 SYN, 服务端以为建立了连接,客户端却没收到,服务端会一直往一个不存在的客户端发数据。</p><p>三次握手还顺带确认了<strong>双方的初始序列号</strong>(ISN)能正确送达, TCP 用 seq/ack 相对编号来保证可靠性,必须双方都确认过初始序号。</p><h3 id="q2-四次挥手为什么不是三次" tabindex="-1">Q2：四次挥手为什么不是三次? <a class="header-anchor" href="#q2-四次挥手为什么不是三次" aria-label="Permalink to &quot;Q2：四次挥手为什么不是三次?&quot;">​</a></h3><p>因为 <strong>TCP 是全双工的</strong>:一个方向的关闭需要两个 FIN/ACK 往返。</p><ul><li>客户端发 FIN → 服务端收到,TCP 协议规定「<strong>此时客户端不再发送数据,但仍能接收</strong>」,所以服务端不能立刻发 FIN</li><li>服务端要把剩余数据发完,再发自己的 FIN → 客户端回 ACK</li><li>所以是 <strong>FIN / ACK / FIN / ACK</strong> 四次</li></ul><p><strong>如果服务端收到 FIN 时恰好也没有数据要发</strong>,可以把 ACK 和 FIN 合并成一个包, 这时就变成三次。所以「四次」是常规情况,「三次」是特殊情况。</p><h3 id="q3-time-wait-是什么-为什么需要它-为什么要等-2msl" tabindex="-1">Q3：TIME_WAIT 是什么?为什么需要它?为什么要等 2MSL? <a class="header-anchor" href="#q3-time-wait-是什么-为什么需要它-为什么要等-2msl" aria-label="Permalink to &quot;Q3：TIME_WAIT 是什么?为什么需要它?为什么要等 2MSL?&quot;">​</a></h3><p>主动关闭方在发出最后一个 ACK 后进入 TIME_WAIT(默认 2MSL,MSL 是最大报文寿命,通常 2 分钟)。</p><p><strong>两个原因</strong>:</p><ol><li><strong>保证最后一个 ACK 能被对方收到</strong>:如果 ACK 丢了,对方会重发 FIN, 这时本端还在 TIME_WAIT 里,还能补发一个 ACK。否则连接会僵死在对端</li><li><strong>让本次连接的旧报文在网络中消失</strong>:避免本次连接的延迟报文,干扰后续 相同四元组的新连接(源 IP/端口/目的 IP/端口 相同但协议不同的旧包,可能被新连接误收)</li></ol><p><strong>代价</strong>:短时间内大量连接会占用端口(「端口耗尽」), 高并发短连接场景要开 <code>SO_REUSEADDR</code>,或者用长连接。</p><h3 id="q4-大量-time-wait-端口耗尽怎么解决" tabindex="-1">Q4：大量 TIME_WAIT / 端口耗尽怎么解决? <a class="header-anchor" href="#q4-大量-time-wait-端口耗尽怎么解决" aria-label="Permalink to &quot;Q4：大量 TIME_WAIT / 端口耗尽怎么解决?&quot;">​</a></h3><p>先分清是<strong>主动关闭方</strong>堆积还是被动方堆积——TIME_WAIT 永远在<strong>主动关闭方</strong>。</p><p>解决方向:</p><ol><li><strong>连接复用</strong>:用 keep-alive 长连接,减少连接建立/关闭次数(最有效)</li><li><strong>调内核参数</strong>:<code>net.ipv4.tcp_tw_reuse=1</code> 允许 TIME_WAIT 状态下重新绑定端口 (<code>tcp_tw_recycle</code> 已废弃,不要用)</li><li><strong>扩端口范围</strong>:<code>net.ipv4.ip_local_port_range = 10000 65535</code></li><li><strong>多网卡 / 多源 IP 出口</strong>:绕开四元组冲突</li><li><strong>SO_REUSEADDR</strong>:允许绑定处于 TIME_WAIT 的本地地址</li></ol><p><strong>根治</strong>:如果业务是「客户端主动连服务端」的短连接模型,TIME_WAIT 会集中在客户端, 这时应该考虑让<strong>服务端主动关闭</strong>或改成长连接。</p><h2 id="📝-小结" tabindex="-1">📝 小结 <a class="header-anchor" href="#📝-小结" aria-label="Permalink to &quot;📝 小结&quot;">​</a></h2><ul><li>三次握手的本质是让双方都确认「收发能力」并交换初始序列号,两次无法确认服务端发给客户端的报文可达。</li><li>四次挥手是因为 TCP 全双工,一个方向关闭要两个往返;服务端无数据待发时 ACK 和 FIN 可合并成三次。</li><li>TIME_WAIT 在主动关闭方,有两个目的:兜底重传的 ACK、让旧报文在网络中消失(2MSL)。</li><li>端口耗尽的根治是连接复用(长连接),内核参数只是缓解。</li></ul>',28)])])}const A=o(i,[["render",l]]);export{T as __pageData,A as default};
